const icon=(name)=>({play:'▶',pause:'Ⅱ',previous:'◀◀',next:'▶▶',clipboard:'▤',battery:'ϟ',settings:'⚙',calendar:'▦'}[name]||name);
function waves(){return `<span class="wave" aria-hidden="true">${[0,1,2,3,4].map(i=>`<i style="--i:${i}"></i>`).join('')}</span>`}
function week(){return `<div class="week"><b>${tr('Nov','11月')}</b><div>${['31','01','02','03','04','05','06'].map((d,i)=>`<span class="${i===2?'today':''}"><small>${tr(['S','S','M','T','W','T','F'][i],['六','日','一','二','三','四','五'][i])}</small><strong>${d}</strong><i></i></span>`).join('')}</div></div>`}
function moduleMarkup(){return `<section class="demo-module music-module" aria-label="${tr('Music demo','音乐演示')}"><div class="demo-art" aria-hidden="true"><span>o</span><i></i><small>ORBI SESSIONS</small></div><div class="demo-track"><div><strong class="track-title">A Little More Space</strong><small class="artist">Orbi Sessions</small></div><div class="playback"><button data-track="-1" aria-label="${tr('Previous sample track','上一首示例曲目')}">◀◀</button><button class="play-toggle" aria-label="${tr('Pause demo','暂停演示')}" aria-pressed="true">Ⅱ</button><button data-track="1" aria-label="${tr('Next sample track','下一首示例曲目')}">▶▶</button></div><div class="progress-row"><span class="elapsed">0:48</span><input class="demo-progress" type="range" min="0" max="246" value="48" aria-label="${tr('Demo playback position','演示播放进度')}"><span class="remaining">−3:18</span></div></div></section>
<section class="demo-module calendar-module" aria-label="${tr('Calendar demo','日历演示')}">${week()}<div class="demo-event"><i></i><span>${tr('A day for good ideas','给好想法的一天')}</span><small>${tr('All day','全天')}</small></div><div class="demo-event"><i></i><span>${tr('Design catch-up','设计讨论')}</span><small>13:00–14:00</small></div></section>
<section class="demo-module clipboard-module" aria-label="${tr('Clipboard demo','剪贴板演示')}"><div class="clipboard-count"><span>3</span><button class="clear-samples" aria-label="${tr('Clear demo history','清空示例历史')}">⌫</button></div><div class="sample-list">${[tr('Keep good ideas moving.','让好想法，继续流动。'),'https://example.com',tr('A little more space for today.','为今天，多留一点空间。')].map(s=>`<button class="sample-clip"><span aria-hidden="true">▤</span><span>${s}</span></button>`).join('')}</div><div class="clipboard-empty" hidden><span>▤</span><div><strong>${tr('Clipboard ready','剪贴板已就绪')}</strong><small>${tr('Copy text to begin','复制文本即可开始')}</small></div></div></section>`}
function productPage(){return `
<section class="hero product-hero"><div class="eyebrow">ORBI 1.2 · MADE FOR MAC</div><h1>${tr('Small space.<br><span>More possibilities.</span>','小小刘海。<br><span>大有可为。</span>')}</h1><p>${tr('Your music, your day, your next good idea.<br>All a little closer. Right at the top of your Mac.','音乐、日程、刚复制的好想法。<br>轻轻移入，在 Mac 顶部展开你的日常。')}</p><div class="actions"><a class="pill" href="/download/">${tr('Get Orbi 1.2','下载 Orbi 1.2')} <span>↗</span></a><a class="textlink" href="#product-demo">${tr('Take a closer look','亲手试试')} ↓</a></div><div class="hero-meta">macOS ${RELEASE.minimumOS}+ <span>·</span> Apple silicon & Intel</div></section>
<section class="demo-section" id="product-demo" aria-label="${tr('Interactive Orbi preview','Orbi 交互预览')}"><div class="desktop-demo"><div class="desktop-menubar" aria-hidden="true"><span>● &nbsp; Finder &nbsp; File &nbsp; Edit</span><span>Mon 9:41</span></div><div class="demo-notch playing" id="interactive-notch"><button class="notch-trigger" aria-expanded="false" aria-controls="demo-modules" aria-label="${tr('Expand Orbi demo','展开 Orbi 演示')}"><span class="compact-left">♫</span><span class="camera-space"></span><span class="compact-right">${waves()}</span></button><div class="notch-modules" id="demo-modules" inert>${moduleMarkup()}</div><button class="demo-gear" hidden aria-label="${tr('Preview Orbi settings','预览 Orbi 设置')}">⚙</button></div><div class="desktop-motif" aria-hidden="true"><span class="orbit-line"></span><span>orbi</span><small>${tr('Right where you need it.','需要的，刚好在这里。')}</small></div><div class="demo-instruction">${tr('Hover over the notch. Click to keep it open.','将鼠标移入刘海，点击可保持展开。')}</div><div class="demo-toast" role="status" aria-live="polite"></div></div>
<div class="demo-controls" role="group" aria-label="${tr('Preview a notch state','选择演示状态')}">${[['idle',tr('Standby','待机')],['music',tr('Music','音乐')],['charge',tr('Charging','充电')],['low',tr('Low battery','低电量')]].map(([mode,label])=>`<button data-demo-mode="${mode}" aria-pressed="${mode==='music'}">${label}</button>`).join('')}<button class="expand-demo">${tr('Expand workspace','展开工作区')} ↗</button></div><p class="caption">${tr('Interactive preview with sample content. It does not access your music, calendar, or clipboard.','交互预览使用示例内容，不会读取你的音乐、日历或剪贴板。')}</p></section>
<section class="section intro-section"><div class="eyebrow">A NEW SHAPE OF EVERYDAY</div><h2>${tr('Made to belong.<br><span>Built to open up.</span>','贴合屏幕。<br><span>也贴近日常。</span>')}</h2><p>${tr('The new expanded workspace curves into your screen edge. Bigger artwork, clearer type, and room for everything you reach for. One smooth move, and it’s all there.','全新的反向圆弧，与屏幕顶部自然衔接。更大的封面、更清晰的文字，以及舒展有序的布局。一次轻轻移入，常用的工具就都在眼前。')}</p></section>
<section class="section features"><div class="feature-grid">${featureCards().map((c,i)=>`<article class="feature-card feature-${i}"><span class="feature-number">0${i+1} / ${c[0]}</span><div class="feature-symbol" aria-hidden="true">${c[1]}</div><h3>${c[2]}</h3><p>${c[3]}</p></article>`).join('')}</div></section>
<section class="power-section"><div class="section split"><div><div class="eyebrow">CONNECTED, AT A GLANCE</div><h2>${tr('A little energy.<br><span>Right in view.</span>','充电的那一刻。<br><span>抬眼就知道。</span>')}</h2><p>${tr('Plug in, and the notch extends with your battery percentage. Below 20%, it keeps an amber reminder in view. Play music, and the music indicator takes its place. Separate states. The same considered shape.','连接电源，刘海两侧展开充电图标和百分比。低于 20%，橙色电量提醒持续可见。开始播放音乐，便自动切换到音乐状态。独立的提示，一样协调的形态。')}</p><button class="textlink" data-try-power>${tr('Try the charging state','试试充电状态')} ↑</button></div><div class="power-visual" aria-hidden="true"><div class="power-notch"><span>ϟ</span><span>82<small>%</small></span></div><div class="power-percentage">82<span>%</span></div><small>${tr('A little more power for your day.','为接下来的日常，充一点电。')}</small></div></div></section>
<section class="section settings-section"><div class="section-heading"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>${tr('Your tools.<br><span>Your way.</span>','你的工具。<br><span>你的使用方式。</span>')}</h2><p>${tr('A new settings center, with search, clear categories, and a place for every permission. Choose what belongs in your workspace.','全新设置中心，搜索、分类导航与权限状态一目了然。选择工作区里需要的模块，让 Orbi 更适合你的习惯。')}</p></div><div class="settings-demo"><aside><div class="settings-brand"><img src="/assets/orbi-icon.png" alt="" width="34" height="34"><strong>Orbi</strong></div>${[['workspace',tr('Workspace','工作区'),'▤'],['battery',tr('Battery & Alerts','电池与提醒'),'ϟ'],['permissions',tr('Permissions','权限'),'✓'],['updates',tr('Software Update','软件更新'),'↓']].map(([k,t,i])=>`<button data-settings-page="${k}" class="${k==='workspace'?'selected':''}" aria-pressed="${k==='workspace'}"><i>${i}</i>${t}</button>`).join('')}<small>${tr('Website preview','网页预览')}</small></aside><div class="settings-demo-content" id="settings-demo-content"></div></div><p class="caption">${tr('Try the settings preview. Changes affect this webpage only.','试试切换设置页面。这里的修改仅影响网页演示。')}</p></section>
<section class="section whats-new-teaser"><div><span class="eyebrow">NEW IN VERSION 1.2</span><h2>${tr('A little more.<br>In every detail.','每一处，<br>都更进一步。')}</h2></div><div><p>${tr('A redesigned workspace. Independent battery indicators. A complete permissions view. Updates from inside the app. This is Orbi 1.2.','重新设计的展开面板、独立电量提示、完整的权限状态，以及应用内更新。这就是 Orbi 1.2。')}</p><a class="textlink" href="/download/#whats-new">${tr('See everything that’s new','查看完整更新内容')} ↗</a></div></section><section class="section closing"><img src="/assets/orbi-icon.png" alt="" width="78" height="78"><h2>${tr('Make room<br><span>for a better everyday.</span>','为日常，<br><span>多留一点可能。</span>')}</h2><a class="pill" href="/download/">${tr('Get Orbi 1.2','下载 Orbi 1.2')} ↗</a></section>`}
function featureCards(){return lang==='zh'?[
['APPLE MUSIC','♫','下一首，不必切走。','大封面、歌曲与歌手、播放控制和进度。Apple Music 打开时就显示音乐卡片，暂停后也会保留。'],
['CALENDAR','▦','今天，安排得明明白白。','月份与日期条，搭配全天、进行中或接下来的日程。抬眼就知道下一步。'],
['CLIPBOARD','▤','刚才复制的，还在。','保留最近 15 条文本，点击重新复制，一键清空。历史保存在本机内存，退出即清除。'],
['BATTERY','ϟ','连接电源，自然出现。','独立显示充电与低电量状态。音乐和电量等宽切换，充电提示音不会触发音乐卡片。'],
['PERMISSIONS','✓','授权情况，看得清楚。','系统音频、Apple Music 自动化、日历、剪贴板和登录启动，都有对应状态与设置入口。'],
['SOFTWARE UPDATE','↓','下一次更新，就在这里。','从设置里检查更新，也可开启自动检查和下载。有新版本时，在应用内安装并重新启动。']
]:[
['APPLE MUSIC','♫','Next track. Same focus.','Larger artwork, song details, controls and progress. The Music card stays available whenever Apple Music is open, even while paused.'],
['CALENDAR','▦','Your day, a little clearer.','A month and date strip, with all-day, ongoing or upcoming events. Know what comes next at a glance.'],
['CLIPBOARD','▤','Copied. Still within reach.','Your last 15 copied texts. Click to copy again, or clear them in one step. History stays in memory and clears on quit.'],
['BATTERY','ϟ','Plug in. Stay in the know.','Separate charging and low-battery indicators. Music takes over at the same width. The charger chime stays out of your music state.'],
['PERMISSIONS','✓','A clear view of access.','Review system audio, Apple Music automation, calendar, clipboard and login startup, with the relevant settings close by.'],
['SOFTWARE UPDATE','↓','The next version, right here.','Check for updates in settings, or opt in to automatic checks and downloads. Install and relaunch from inside Orbi.']
]}
window.demoCleanup=()=>{};
function setupProduct(){
 const notch=document.querySelector('#interactive-notch'),trigger=notch.querySelector('.notch-trigger'),modules=notch.querySelector('.notch-modules'),gear=notch.querySelector('.demo-gear');
 let pinned=false,open=false,timer,toastTimer,mode='music',playing=true,track=0,elapsed=48,settingsPage='workspace';
 const enabled={music:true,calendar:true,clipboard:true},tracks=['A Little More Space','Blue Hour','Quiet Morning'];
 function setOpen(value){open=value;notch.classList.toggle('expanded',value);trigger.setAttribute('aria-expanded',String(value));trigger.setAttribute('aria-label',value?tr('Collapse Orbi demo','收起 Orbi 演示'):tr('Expand Orbi demo','展开 Orbi 演示'));modules.inert=!value;gear.hidden=!value}
 function setMode(value){mode=value;playing=value==='music';notch.dataset.mode=value;notch.classList.toggle('playing',playing);notch.classList.toggle('idle',value==='idle');notch.querySelector('.compact-left').textContent=value==='charge'?'ϟ':value==='low'?'▱':'♫';notch.querySelector('.compact-right').innerHTML=value==='charge'?'82%':value==='low'?'19%':waves();notch.querySelector('.play-toggle').textContent=playing?'Ⅱ':'▶';notch.querySelector('.play-toggle').setAttribute('aria-pressed',String(playing));notch.querySelector('.play-toggle').setAttribute('aria-label',playing?tr('Pause demo','暂停演示'):tr('Play demo','播放演示'));document.querySelectorAll('[data-demo-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.demoMode===value)))}
 function toast(value){const node=document.querySelector('.demo-toast');node.textContent=value;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),2200)}
 trigger.onclick=()=>{pinned=!pinned;setOpen(pinned)};
 notch.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){clearTimeout(timer);setOpen(true)}});
 notch.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!pinned)timer=setTimeout(()=>setOpen(false),420)});
 notch.addEventListener('keydown',e=>{if(e.key==='Escape'){pinned=false;setOpen(false);trigger.focus()}});
 notch.addEventListener('focusout',e=>{if(!notch.contains(e.relatedTarget)&&!pinned)setOpen(false)});
 document.querySelector('.expand-demo').onclick=()=>{pinned=!open;setOpen(pinned)};
 document.querySelectorAll('[data-demo-mode]').forEach(b=>b.onclick=()=>{pinned=false;setOpen(false);setMode(b.dataset.demoMode)});
 notch.querySelector('.play-toggle').onclick=()=>setMode(playing?'idle':'music');
 notch.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{track=(track+Number(b.dataset.track)+tracks.length)%tracks.length;elapsed=0;notch.querySelector('.track-title').textContent=tracks[track];updateTime()});
 function updateTime(){const fmt=n=>Math.floor(n/60)+':'+String(n%60).padStart(2,'0');notch.querySelector('.elapsed').textContent=fmt(elapsed);notch.querySelector('.remaining').textContent='−'+fmt(246-elapsed);notch.querySelector('.demo-progress').value=elapsed}
 notch.querySelector('.demo-progress').oninput=e=>{elapsed=Number(e.target.value);updateTime()};
 const clock=setInterval(()=>{if(playing&&!document.hidden){elapsed=(elapsed+1)%247;updateTime()}},1000);
 notch.querySelectorAll('.sample-clip').forEach(b=>b.onclick=()=>{notch.querySelectorAll('.sample-clip').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');toast(tr('Sample selected — your clipboard is unchanged.','已选中示例，不会修改你的剪贴板。'))});
 notch.querySelector('.clear-samples').onclick=()=>{notch.querySelector('.sample-list').hidden=true;notch.querySelector('.clipboard-count').hidden=true;notch.querySelector('.clipboard-empty').hidden=false;toast(tr('Demo history cleared.','示例历史已清空。'))};
 document.querySelector('[data-try-power]').onclick=()=>{pinned=false;setOpen(false);setMode('charge');document.querySelector('#product-demo').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
 function settingsView(key){settingsPage=key;document.querySelectorAll('[data-settings-page]').forEach(b=>{b.classList.toggle('selected',b.dataset.settingsPage===key);b.setAttribute('aria-pressed',String(b.dataset.settingsPage===key))});const node=document.querySelector('#settings-demo-content');const titles={workspace:tr('Your workspace','你的工作区'),battery:tr('Battery & Alerts','电池与提醒'),permissions:tr('Permissions','权限'),updates:tr('Software Update','软件更新')};let body='';if(key==='workspace')body=['music','calendar','clipboard'].map(k=>`<label class="preview-setting"><span>${tr({music:'Music',calendar:'Calendar',clipboard:'Clipboard'}[k],{music:'音乐',calendar:'日历',clipboard:'剪贴板'}[k])}</span><input type="checkbox" data-module="${k}" ${enabled[k]?'checked':''}></label>`).join('');if(key==='battery')body=`<div class="preview-setting"><span>${tr('Charging','正在充电')}</span><b class="green">ϟ 82%</b></div><div class="preview-setting"><span>${tr('Low battery threshold','低电量阈值')}</span><b>20%</b></div>`;if(key==='permissions')body=['Apple Music',tr('Calendar','日历'),tr('Clipboard','剪贴板')].map(x=>`<div class="preview-setting"><span>${x}</span><b class="green">${tr('Example: allowed','示例：已授权')}</b></div>`).join('');if(key==='updates')body=`<div class="preview-setting"><strong>Orbi 1.2</strong><span>${tr('Current release','当前版本')}</span></div><div class="preview-setting"><span>${tr('Check for updates','检查更新')}</span><a href="/download/#whats-new">${tr('What’s new ↗','更新内容 ↗')}</a></div>`;node.innerHTML=`<span class="settings-hero-icon">${{workspace:'▤',battery:'ϟ',permissions:'✓',updates:'↓'}[key]}</span><h3>${titles[key]}</h3><div class="preview-setting-group">${body}</div>`;node.querySelectorAll('[data-module]').forEach(input=>input.onchange=()=>{enabled[input.dataset.module]=input.checked;notch.querySelector('.'+input.dataset.module+'-module').hidden=!input.checked;if(!Object.values(enabled).some(Boolean)){toast(tr('All preview modules hidden.','演示模块已全部隐藏。'))}})}
 document.querySelectorAll('[data-settings-page]').forEach(b=>b.onclick=()=>settingsView(b.dataset.settingsPage));
 gear.onclick=()=>{settingsView('workspace');document.querySelector('.settings-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
 settingsView('workspace');setMode('music');
 window.demoCleanup=()=>{clearInterval(clock);clearTimeout(timer);clearTimeout(toastTimer)};
}
